const $=id=>document.getElementById(id);let token='',page=1,epoch=0;
const editor=$('editor');const notice=s=>$('notice').textContent=s;
async function api(path='',options={}){const r=await fetch('/api/admin/documents'+path,{...options,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'}});if(!r.ok){const d=await r.json();throw Error(d.error)}return r}
async function load(){const generation=++epoch;const d=await(await api('?page='+page)).json();if(generation!==epoch||!token)return;$('rows').replaceChildren();for(const x of d.items){const tr=document.createElement('tr');for(const val of [x.title,x.category,x.entity_id,x.size,x.created_at]){const td=document.createElement('td');td.textContent=val;tr.append(td)}const td=document.createElement('td'),b=document.createElement('button');b.textContent='Télécharger';b.onclick=async()=>{const active=token;try{const blob=await(await api('/'+x.id)).blob();if(!token||token!==active)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=x.id+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){notice(e.message)}};td.append(b);tr.append(td);$('rows').append(tr)}$('pages').textContent='Page '+page+' · '+d.total+' document(s)';$('prev').disabled=page===1;$('next').disabled=page*25>=d.total}
async function refresh(){try{await load()}catch(e){notice(e.message)}}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';page=1;try{await load();$('login').hidden=true;$('workspace').hidden=false;notice('Connecté.')}catch(e){token='';notice(e.message)}};
$('logout').onclick=()=>{epoch++;token='';editor.reset();$('rows').replaceChildren();$('pages').textContent='';$('workspace').hidden=true;$('login').hidden=false;notice('Déconnecté.')};
editor.onsubmit=async e=>{e.preventDefault();const active=token,form=new FormData(editor),file=form.get('pdf');$('save').disabled=true;try{if(!file.size||file.size>1048576)throw Error('PDF de 1 Mio maximum.');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));if(!token||token!==active)return;await api('',{method:'POST',body:JSON.stringify({category:form.get('category'),entity_id:form.get('entity_id').trim(),title:form.get('title'),content:btoa(raw)})});if(token===active){editor.reset();page=1;await load();notice('Document enregistré.')}}catch(e){notice(e.message)}finally{$('save').disabled=false}};
$('prev').onclick=()=>{if(page>1){page--;refresh()}};$('next').onclick=()=>{page++;refresh()};
